<body>
    <div class="container">
        <div class="header">
            <h1>  PDF转图片工具</h1>
            <p>将PDF文件的每一页转换为高质量JPG图片</p>
        </div>

        <div class="content">
            <div class="upload-area" id="uploadArea">
                <div class="upload-icon"> </div>
                <div class="upload-text">点击选择PDF文件或拖拽文件到此处</div>
                <button class="btn" onclick="document.getElementById('fileInput').click()">选择文件</button>
                <input type="file" id="fileInput" class="file-input" accept=".pdf" />
            </div>

            <div class="file-info" id="fileInfo">
                <h3>  文件信息</h3>
                <p id="fileName"></p>
                <p id="fileSize"></p>
                <p id="pageCount"></p>
            </div>

            <div class="settings">
                <h3 style="margin-bottom: 20px; color: #374151;">⚙️ 导出设置</h3>

                <div class="setting-group">
                    <label class="setting-label" for="quality">图片质量 (0.1-1.0)</label>
                    <input type="number" id="quality" class="setting-input" min="0.1" max="1.0" step="0.1" value="0.9" />
