                <div class="setting-group">
                    <label class="setting-label" for="scale">渲染比例 (1-3)</label>
                    <input type="number" id="scale" class="setting-input" min="1" max="3" step="0.5" value="2" />
                </div>

                <div class="setting-group">
                    <label class="setting-label" for="format">输出格式</label>
                    <select id="format" class="setting-input">
                        <option value="jpeg">JPEG</option>
                        <option value="png">PNG</option>
                    </select>
                </div>
            </div>

            <div class="progress-container" id="progressContainer">
                <h3 style="margin-bottom: 15px; color: #374151;">  转换进度</h3>
                <div class="progress-bar">
                    <div class="progress-fill" id="progressFill"></div>
                </div>
                <div class="progress-text" id="progressText">准备中...</div>
            </div>

            <div class="controls">
                <div class="btn-group">
                    <button class="btn" id="convertBtn" onclick="convertPDF()" disabled>  开始转换</button>
                    <button class="btn" id="downloadBtn" onclick="downloadZip()" disabled style="display: none;">  下载ZIP文件</button>
                    <button class="btn" onclick="reset()" style="background: #6b7280;">  重置</button>
                </div>
            </div>

            <div class="preview-container" id="previewContainer">
                <h3 style="color: #374151; margin-bottom: 15px;"> ️ 预览</h3>
                <div class="preview-grid" id="previewGrid"></div>
            </div>
        </div>
    </div>

    <script type="module">
        // 导入PDF.js
        import * as pdfjsLib from 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.0.379/pdf.min.mjs';

        // 设置PDF.js worker
        pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.0.379/pdf.worker.min.mjs';

        let pdfDoc = null;
        let convertedImages = [];
        let currentFile = null;

        // 文件拖拽处理
        const uploadArea = document.getElementById('uploadArea');
        const fileInput = document.getElementById('fileInput');

        uploadArea.addEventListener('dragover', (e) => {
            e.preventDefault();
            uploadArea.classList.add('dragover');
        });

        uploadArea.addEventListener('dragleave', () => {
            uploadArea.classList.remove('dragover');
        });

        uploadArea.addEventListener('drop', (e) => {
            e.preventDefault();
            uploadArea.classList.remove('dragover');
            const files = e.dataTransfer.files;
            if (files.length > 0 && files[0].type === 'application/pdf') {
                handleFile(files[0]);
            } else {
                alert('请选择PDF文件！');
            }
        });

        uploadArea.addEventListener('click', () => {
            fileInput.click();
        });

        fileInput.addEventListener('change', (e) => {
            if (e.target.files.length > 0) {
                handleFile(e.target.files[0]);
            }
        });

        // 处理文件
        async function handleFile(file) {
            if (file.type !== 'application/pdf') {
                alert('请选择PDF文件！');
                return;
            }

            currentFile = file;
            const fileReader = new FileReader();

            fileReader.onload = async function() {
                try {
                    // 加载PDF
                    const typedArray = new Uint8Array(this.result);
                    pdfDoc = await pdfjsLib.getDocument(typedArray).promise;

                    // 显示文件信息
                    showFileInfo(file, pdfDoc.numPages);

                    // 启用转换按钮
                    document.getElementById('convertBtn').disabled = false;
                } catch (error) {
                    console.error('PDF加载失败:', error);
                    alert('PDF文件加载失败，请检查文件是否损坏。');
                }
            };

            fileReader.readAsArrayBuffer(file);
        }

        // 显示文件信息
        function showFileInfo(file, pageCount) {
            const fileInfo = document.getElementById('fileInfo');
            const fileName = document.getElementById('fileName');
            const fileSize = document.getElementById('fileSize');
            const pageCountEl = document.getElementById('pageCount');

            fileName.textContent = `文件名: ${file.name}`;
            fileSize.textContent = `文件大小: ${(file.size / 1024 / 1024).toFixed(2)} MB`;
            pageCountEl.textContent = `总页数: ${pageCount} 页`;

            fileInfo.style.display = 'block';
        }

        // 转换PDF
        window.convertPDF = async function() {
            if (!pdfDoc) {
                alert('请先选择PDF文件！');
                return;
            }

            const quality = parseFloat(document.getElementById('quality').value);
            const scale = parseFloat(document.getElementById('scale').value);
            const format = document.getElementById('format').value;

            const progressContainer = document.getElementById('progressContainer');
            const progressFill = document.getElementById('progressFill');
            const progressText = document.getElementById('progressText');
            const convertBtn = document.getElementById('convertBtn');

            // 显示进度条
            progressContainer.style.display = 'block';
            convertBtn.disabled = true;
            convertedImages = [];

            // 清空预览
            document.getElementById('previewGrid').innerHTML = '';
            document.getElementById('previewContainer').style.display = 'none';

            try {
                const totalPages = pdfDoc.numPages;

                for (let pageNum = 1; pageNum <= totalPages; pageNum++) {
                    // 更新进度
                    const progress = ((pageNum - 1) / totalPages) * 100;
                    progressFill.style.width = progress + '%';
                    progressText.textContent = `正在转换第 ${pageNum} 页 / 共 ${totalPages} 页...`;

                    // 获取页面
                    const page = await pdfDoc.getPage(pageNum);

                    // 设置渲染参数
                    const viewport = page.getViewport({ scale: scale });

                    // 创建canvas
                    const canvas = document.createElement('canvas');
                    const context = canvas.getContext('2d');
                    canvas.height = viewport.height;
                    canvas.width = viewport.width;

                    // 渲染页面
                    await page.render({
                        canvasContext: context,
                        viewport: viewport
                    }).promise;

                    // 转换为图片
                    const mimeType = format === 'png' ? 'image/png' : 'image/jpeg';
                    const imageDataUrl = canvas.toDataURL(mimeType, quality);

                    // 存储图片数据
                    const fileName = currentFile.name.replace('.pdf', '');
                    const pageFileName = `${fileName}_第${pageNum.toString().padStart(3, '0')}页.${format === 'png' ? 'png' : 'jpg'}`;

                    convertedImages.push({
                        name: pageFileName,
                        dataUrl: imageDataUrl,
                        pageNum: pageNum
                    });

                    // 添加预览
                    addPreview(imageDataUrl, pageFileName);

                    // 小延迟，让UI更新
                    await new Promise(resolve => setTimeout(resolve, 10));
                }

                // 完成
                progressFill.style.width = '100%';
                progressText.textContent = `转换完成！共生成 ${totalPages} 张图片`;

                // 显示下载按钮
                document.getElementById('downloadBtn').style.display = 'inline-block';
                document.getElementById('downloadBtn').disabled = false;

                // 显示预览
                document.getElementById('previewContainer').style.display = 'block';

            } catch (error) {
                console.error('转换失败:', error);
                alert('转换失败: ' + error.message);
            } finally {
                convertBtn.disabled = false;
            }
        };

        // 添加预览
        function addPreview(imageDataUrl, fileName) {
            const previewGrid = document.getElementById('previewGrid');

            const previewItem = document.createElement('div');
            previewItem.className = 'preview-item';

            const img = document.createElement('img');
            img.src = imageDataUrl;
            img.className = 'preview-image';
            img.alt = fileName;

            const info = document.createElement('div');
            info.className = 'preview-info';
            info.textContent = fileName;

            previewItem.appendChild(img);
            previewItem.appendChild(info);
            previewGrid.appendChild(previewItem);
        }

        // 下载ZIP文件
        window.downloadZip = async function() {
            if (convertedImages.length === 0) {
                alert('没有可下载的图片！');
                return;
            }

            try {
                const zip = new JSZip();
                const folderName = currentFile.name.replace('.pdf', '') + '_图片';
                const folder = zip.folder(folderName);

                // 添加所有图片到ZIP
                for (const image of convertedImages) {
                    // 将dataURL转换为blob
                    const response = await fetch(image.dataUrl);
                    const blob = await response.blob();
                    folder.file(image.name, blob);
                }

                // 生成ZIP文件
                const content = await zip.generateAsync({ type: 'blob' });

                // 下载ZIP文件
                const url = URL.createObjectURL(content);
                const a = document.createElement('a');
                a.href = url;
                a.download = folderName + '.zip';
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                URL.revokeObjectURL(url);

                alert('下载完成！解压ZIP文件即可获得所有图片。');
            } catch (error) {
                console.error('下载失败:', error);
                alert('下载失败: ' + error.message);
            }
        };

        // 重置
        window.reset = function() {
            pdfDoc = null;
            convertedImages = [];
            currentFile = null;

            document.getElementById('fileInfo').style.display = 'none';
            document.getElementById('progressContainer').style.display = 'none';
            document.getElementById('previewContainer').style.display = 'none';
            document.getElementById('convertBtn').disabled = true;
            document.getElementById('downloadBtn').style.display = 'none';
            document.getElementById('fileInput').value = '';
            document.getElementById('previewGrid').innerHTML = '';
        };
    </script>
</body>
</html>
```

简单到只有几个按钮，用法应该也不用我多说了。

![](https://picx.zhimg.com/v2-8235d54b432ec0de38032432ef1baaf2\_r.jpg?source=d16d100b)![](https://pic1.zhimg.com/v2-0c7650646630c89db3eeab36e30aeb66\_r.jpg?source=d16d100b)

②前往**「PPT内容识别」**表格中，使用固定在右上角侧边栏的**「批量上传附件」**插件批量上传每一页截图。

![](https://picx.zhimg.com/v2-5ae4aabea15a9081bd3716dda5e2af5e\_r.jpg?source=d16d100b)

③双击**「内容识别」**，为AI图片理解字段捷径配置豆包大模型账号。
建议使用Doubao-1.5-vision-pro模型，如果你希望AI更加忠实于原文并减少延展，也可以使用Doubao-Seed-1.6。

![](https://pic1.zhimg.com/v2-f5cfc1ba96fe8aa78bc3f4e7ff44c4a2\_r.jpg?source=d16d100b)![](https://picx.zhimg.com/v2-25a31e59125f23f72f12d44419e93488\_r.jpg?source=d16d100b)

（可以参加火山方舟的协作奖励计划，每天领取50w tokens。）

配置好后，豆包大模型开始理解每一张PPT页面并进行总结。

**经过PPT排版和美化后的分区块不连贯内容**，**也可以被豆包大模型理解并总结**。

④**手动录入**图片字段左侧的**「页码编号」**字段和**「资料名称」**字段，支持像Excel一样拖动填充柄进行填充。

页码录入会关联右侧公式字段，公式内带有Markdown标题标记，以便于后续创建飞书文档时自动识别页码标题。

![](https://picx.zhimg.com/v2-b47b8d2aeec959cf9a2731f472e911e1\_r.jpg?source=d16d100b)![](https://pica.zhimg.com/v2-e534469c3151b96052cd90aa3fde6c1c\_r.jpg?source=d16d100b)

### 文本类PDF（非扫描）请这样操作：

①前往**「PDF文档提取」**表格中，在下拉列表中选择相应的资料名称。

![](https://pica.zhimg.com/v2-dc3a3d3f68bc2d1a514b33af645f2c9d\_r.jpg?source=d16d100b)

②手动将自动匹配出的附件，**复制到右侧PDF文档附件字段**中。

![](https://picx.zhimg.com/v2-01a313a45b83901b6dd238e0c9991ad6\_r.jpg?source=d16d100b)

PDF文档的文字内容会被自动提取到「内容提取」字段。

### 截图类请这样操作：

动作基本跟文本类PDF相同。

①前往**「图片OCR」**表格中，在下拉列表中选择资料相应的资料名称。

②手动将自动匹配出的附件，复制到右侧PDF文档附件字段中。

![](https://picx.zhimg.com/v2-162648efc1dca575e6b3fecf9e18d757\_r.jpg?source=d16d100b)

### 3.生成文档总结和飞书文档

表格默认按照自增编号进行资料匹配，只要在**「1.文件上传&留存」**中上传过的文件，下左图红框内的信息都会自动出现，不需要手动操作。如果上传文件数量超过本表行数导致新传文档未显示出，只需要向下插入新行即可。

![](https://picx.zhimg.com/v2-9023be4671eda85383d9bdf4a4a86124\_r.jpg?source=d16d100b)![](https://picx.zhimg.com/v2-da5e041e65fa03a7db0346f70e42c1dd\_r.jpg?source=d16d100b)

***如果按钮为灰色，需要进入自动化中心手动启用自动化流程。***

![](https://picx.zhimg.com/v2-35c9b40814167b6cf0d68cf31e538193\_r.jpg?source=d16d100b)

按钮生效后，对需要总结的文档点击按钮，则按钮右侧自动生成**「资料内容」、「重点总结」、「飞书文档」**三个字段的内容。

![](https://pic1.zhimg.com/v2-0c65ef5de3e2e7c7ffe28fc5615ff478\_r.jpg?source=d16d100b)

生成飞书文档需要按提示进行扣子授权，授权通过后重新运行字段捷径即可。

飞书文档生成后，就可以在**飞书知识问答**中作为参考信息被AI引用了。

![](https://picx.zhimg.com/v2-147458d5bc821b047bad3ab9422e275e\_r.jpg?source=d16d100b)

使用**「查询页」**，可以查询对应资料的重点信息。

![](https://pic1.zhimg.com/v2-487ecee62818cabbe986d841cb94d765\_r.jpg?source=d16d100b)

表格最右侧几个字段根据资料重点内容总结完成了封面图生成。生图需要消耗一定API费用，默认关闭自动生成，你可以自行选择是否开启。

启用后，**「知识图册」仪表盘的画册组件会带有AI生成的标题封面**：

![](https://pic1.zhimg.com/v2-6ba79aacb22248e9f67b00106b4b0f4f\_r.jpg?source=d16d100b)

画册展示效果是这样：

![](https://pic1.zhimg.com/v2-f7f22507eb9b4c5bf4e87d7cfc55ab13\_r.jpg?source=d16d100b)

### 4.豆包智能决策建议

本功能可实现小范围参考本表格知识库内资料进行解决方案问答。

可通过「参考1」、「参考2」、「参考3」**选择最多3份资料进行参考**，然后**在「问题字段」输入问题**。

则豆包大模型会在「智能建议」字段返回问题的答案/建议。

![](https://pic1.zhimg.com/v2-51313a107cc516fdbea178ae0d038c7c\_r.jpg?source=d16d100b)

问答示例：

> *问题1：我想招聘一个谷歌广告创意策划，帮我出5道题考考他**。***
> *参考：《Google Ads Video Certification学习笔记》*

豆包回答：

[谷歌广告创意策划考察题集](http://link.zhihu.com/?target=https%3A//fh5k77901t.feishu.cn/docx/ZkYedlWmHoNuzBxaMwgch8mLnPd)![](https://picx.zhimg.com/v2-d694c4eb4645b63d354f20cfab135cee\_r.jpg?source=d16d100b)
> *问题2：我们是一家抖音达人电商公司，想在2025年拓展一个AI驱动的像LABUBU一样的潮玩IP业务，有什么AI技术趋势是值得我们关注的吗？*
> *参考：《State of AI Report - 2024 ONLINE》、《2024达人电商全年报》、《LABUBU顶流现象洞察报告》*

豆包回答：

[2025潮玩IP AI技术落地路径](http://link.zhihu.com/?target=https%3A//fh5k77901t.feishu.cn/docx/UGCSdc1qgo2xAjxbUN5csegonTh)![](https://pica.zhimg.com/v2-f25552e40cafecb8c91ef19b82bf6332\_r.jpg?source=d16d100b)

此处豆包大模型选用了Doubao-Seed-1.6模型，直接通过自定义API捷径调用成本相对较低的Doubao-Seed-1.6-flash，表现也不错。

### 5.其他知识剪藏

这两个表格用于碎片化知识快速剪藏，内容不进入上述文档知识库中。

建议配合飞书手机APP使用。

**Web链接剪藏**

适合快捷收藏公众号、小红书等社媒以及博客和网站的内容。

粘贴链接后，可自动总结内容并根据内容生成一个更具概括性的资料名称（过滤自媒体标题党）。

![](https://pica.zhimg.com/v2-e475734d87c4c1dbf2f5136701a98580\_r.jpg?source=d16d100b)

**碎片截图剪藏**

适合快速存储和整理手机截图、群聊图片、朋友圈图片中的有价值信息。

![](https://pica.zhimg.com/v2-beb6b0b38709b6d294afd9c3a1a1cc0d\_r.jpg?source=d16d100b)

以上就是这张表格的全部功能，希望你能喜欢~

---

顺便拉个票，这个模板投稿了多维表格官方的「AI 智能决策创新应用赛」，

如果你觉得它还不错，可以给它点点：

[https://bytedance.larkoffice.com/record/Ldezr5jpLePfvRcUIu0c4Yornef](http://link.zhihu.com/?target=https%3A//bytedance.larkoffice.com/record/Ldezr5jpLePfvRcUIu0c4Yornef)

返回上一层级也有很多其他小伙伴的优秀模板，可以一并收入囊中（狗头

再替官方邀请下隐藏的高手们，如果你有很棒的模板想跟大家分享也可以投稿参赛哦

![](https://picx.zhimg.com/v2-b05d9744517fbcea466fb2cecbf2bd5c\_r.jpg?source=d16d100b)

